+using System;
+using System.Collections.Generic;
+using System.Data;
+using System.Net.Mail;
+using System.Text.RegularExpressions;
+using InformationWebObject;
+namespace InformationWeb
+{
+    public class AdmissionRegistrationBLL
+    {
+        // Lấy danh sách ngành từ object.
+        public DataTable GetCareers()
+        {
+            CRM_RegisterInfo registerInfo = new CRM_RegisterInfo();
+            return registerInfo.GetCareers();
+        }
+        // Kiểm tra dữ liệu hồ sơ.
+        public bool Validate(CRM_RegisterInfo registerInfo, out string message)
+        {
+            List<string> errors = new List<string>();
+            if (string.IsNullOrEmpty(registerInfo.FullName)) errors.Add("Vui lòng nhập họ và tên.");
+            else if (registerInfo.FullName.Length > 50) errors.Add("Họ và tên không vượt quá 50 ký tự.");
+            if (registerInfo.BirthDate == DateTime.MinValue) errors.Add("Ngày sinh không hợp lệ.");
+            else if (registerInfo.BirthDate.Date >= DateTime.Today) errors.Add("Ngày sinh phải nhỏ hơn ngày hiện tại.");
+            if (string.IsNullOrEmpty(registerInfo.IdentityNumber) || !Regex.IsMatch(registerInfo.IdentityNumber, "^(\\d{9}|\\d{12})$")) errors.Add("CMND/CCCD phải gồm 9 hoặc 12 chữ số.");
+            if (string.IsNullOrEmpty(registerInfo.Address)) errors.Add("Vui lòng nhập địa chỉ thường trú.");
+            else if (registerInfo.Address.Length > 1000) errors.Add("Địa chỉ không vượt quá 1000 ký tự.");
+            if (!IsValidPhone(registerInfo.Phone)) errors.Add("Số điện thoại không hợp lệ.");
+            if (!IsValidEmail(registerInfo.Email)) errors.Add("Email không hợp lệ.");
+            if (!registerInfo.CareerID.HasValue || registerInfo.CareerID.Value <= 0 || string.IsNullOrEmpty(registerInfo.CareerName)) errors.Add("Vui lòng chọn ngành đăng ký.");
+            if (!string.IsNullOrEmpty(registerInfo.Description) && registerInfo.Description.Length > 500) errors.Add("Ghi chú không vượt quá 500 ký tự.");
+            message = string.Join(" ", errors.ToArray());
+            return errors.Count == 0;
+        }
+        // Lưu hồ sơ hợp lệ.
+        public long Add(CRM_RegisterInfo registerInfo)
+        {
+            registerInfo.CreatedUser = "website";
+            return registerInfo.AddAdmission() && registerInfo.RegisterInfoID.HasValue ? registerInfo.RegisterInfoID.Value : 0;
+        }
+        // Kiểm tra định dạng điện thoại.
+        private bool IsValidPhone(string phone)
+        {
+            if (string.IsNullOrEmpty(phone) || phone.Length > 20) return false;
+            string digits = Regex.Replace(phone, "[^0-9]", string.Empty);
+            return digits.Length >= 9 && digits.Length <= 15;
+        }
+        // Kiểm tra định dạng email.
+        private bool IsValidEmail(string email)
+        {
+            if (string.IsNullOrEmpty(email) || email.Length > 100) return false;
+            try
+            {
+                MailAddress address = new MailAddress(email);
+                return string.Equals(address.Address, email, StringComparison.OrdinalIgnoreCase);
+            }
+            catch
+            {
+                return false;
+            }
