+    public static class AdmissionUploadHelper
+    {
+        private const int MaxFileSize = 5 * 1024 * 1024;
+        private static readonly string[] AllowedExtensions = { ".jpg", ".jpeg", ".png", ".pdf" };
+        // Kiểm tra file trước khi lưu.
+        public static bool Validate(HttpPostedFile file, out string message)
+        {
+            message = string.Empty;
+            if (file == null || file.ContentLength <= 0) return true;
+            string extension = Path.GetExtension(Path.GetFileName(file.FileName));
+            if (string.IsNullOrEmpty(extension) || Array.IndexOf(AllowedExtensions, extension.ToLowerInvariant()) < 0)
+            {
+                message = "File chỉ chấp nhận định dạng JPG, JPEG, PNG hoặc PDF.";
+                return false;
+            }
+            if (file.ContentLength > MaxFileSize)
+            {
+                message = "Mỗi file tải lên không được vượt quá 5 MB.";
+                return false;
+            }
+            return true;
+        }
