+            if (!Directory.Exists(finalDirectory)) Directory.CreateDirectory(finalDirectory);
+            AdmissionUploadFile uploadFile = new AdmissionUploadFile();
+            uploadFile.TempPath = Path.Combine(tempDirectory, fileName);
+            uploadFile.FinalPath = Path.Combine(finalDirectory, fileName);
+            uploadFile.LogicalPath = String.Format("/Media/Data/Admission/{0}/{1}/{2}", year, month, fileName);
+            file.SaveAs(uploadFile.TempPath);
+            return uploadFile;
+        }
